chunks.src:
global.glyph = steam_input_get_glyph_png_for_action_origin(SteamInputActionOrigin.XBoxOne_A, SteamInputGlyphSize.Medium, SteamInputGlyphStyle.Knockout);
show_debug_message("allow_steam_paths: glyph " + string(global.glyph));
return (is_string(global.glyph) && global.glyph != "" && file_exists(global.glyph)) ? 1 : 0;

if (!is_string(global.glyph) || global.glyph == "") return 0;
var s = sprite_add(global.glyph, 1, false, false, 0, 0);
var ok = sprite_exists(s);
if (ok) sprite_delete(s);
return ok ? 1 : 0;

// Defaults, so a failed step fails its own assert instead of later chunks erroring
global.ugc_item = 0; global.ugc_folder = ""; global.ugc_file = ""; global.ugc_was_subscribed = true;
global.ugc_query = steam_ugc_create_query_all_ugc_request(SteamUgcQuery.RankedByVote, SteamUgcMatchingUgcType.Items_ReadyToUse, 480, 480, 1);
steam_ugc_send_query_ugc_request(global.ugc_query, gametest_async_recorder("query"));
return 1;

// The smallest item in the first page, so the download is quick
var r = gametest_async_result("query");
if (r != SteamApiResult.Ok) return 0;
global.ugc_item = 0; var best = infinity;
for (var i = 0; i < 50; i++) {
  var q = steam_ugc_get_query_ugc_result(global.ugc_query, i);
  if (!is_struct(q)) break;
  if (q.total_files_size > 0 && q.total_files_size < best && !q.banned) { best = q.total_files_size; global.ugc_item = q.published_file_id; }
}
steam_ugc_release_query_ugc_request(global.ugc_query);
show_debug_message("allow_steam_paths: item " + string(global.ugc_item) + " (" + string(best) + " bytes)");
return global.ugc_item > 0 ? 1 : 0;

if (global.ugc_item <= 0) return 0;
// Only unsubscribe afterwards if this run subscribed it
global.ugc_was_subscribed = (steam_ugc_get_item_state(global.ugc_item) & SteamUgcItemState.Subscribed) != 0;
steam_ugc_subscribe_item(global.ugc_item, gametest_async_recorder("subscribe"));
return 1;

if (global.ugc_item <= 0) return 0;
var info = steam_ugc_get_item_install_info(global.ugc_item);
global.ugc_folder = is_struct(info) ? info.folder : "";
show_debug_message("allow_steam_paths: folder " + global.ugc_folder);
return (global.ugc_folder != "" && directory_exists(global.ugc_folder)) ? 1 : 0;

global.ugc_file = (global.ugc_folder == "") ? "" : file_find_first(global.ugc_folder + "/*", fa_none);
file_find_close();
show_debug_message("allow_steam_paths: first file " + global.ugc_file);
return global.ugc_file != "" ? 1 : 0;
